/**
 * test_aes_gcm.c
 *
 * Note: this file was generated by Claude, and checked for correctness by Erik
 * it provides a test case to confirm that AES GCM is working correctly on hardware.
 * To change the test to run with software implementation instead, change
 * wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
 * to
 * wc_AesInit(&aes, NULL, INVALID_DEVID);
 *
 * To run this test, call test_aes_gcm() and test_aes_gcm_errors()
 * and include aes_test.o in the build Makefile.
 *
 * Simple AES-256-GCM encrypt/decrypt round-trip test using wolfcrypt.
 * Exercises the hardware crypto callback registered in hardware_crypto.c.
 *
 * Call test_aes_gcm() from your firmware entry point after calling
 * init_hardware_crypto().
 */

#include <stdint.h>
#include <string.h>

#include <wolfssl/wolfcrypt/settings.h>
#include <wolfssl/wolfcrypt/aes.h>
#include <wolfssl/wolfcrypt/error-crypt.h>

#include "host_messaging.h"
#include "hardware_crypto.h"

/* ------------------------------------------------------------------ */
/*  Test vectors                                                      */
/* ------------------------------------------------------------------ */

/* 256-bit key */
static const uint8_t TEST_KEY[32] = {
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
    0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
    0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
    0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
};

/* 96-bit / 12-byte IV (recommended size for GCM) */
static const uint8_t TEST_IV[12] = {
    0xca, 0xfe, 0xba, 0xbe, 0xfa, 0xce, 0xdb, 0xad,
    0xde, 0xca, 0xf8, 0x88,
};

/* Additional Authentication Data */
static const uint8_t TEST_AAD[] = "header-aad-data";
#define TEST_AAD_SZ ((uint32_t)sizeof(TEST_AAD) - 1)   /* exclude NUL */

/* Plaintext to encrypt */
static const uint8_t TEST_PLAINTEXT[] = "Hello from hardware AES-GCM";
#define TEST_PT_SZ ((uint32_t)sizeof(TEST_PLAINTEXT) - 1)

#define AUTH_TAG_SZ 16u

/* ------------------------------------------------------------------ */
/*  Helpers                                                           */
/* ------------------------------------------------------------------ */

/** Print a byte buffer as hex, with a label. */
static void print_hex(const char *label, const uint8_t *buf, uint32_t len)
{
    print_debug(label);
    char * buffer;
    buffer = (char *)malloc(3*len + 1); /* 2 chars per byte + space, plus NUL */
    for (uint32_t i = 0; i < len; i++) {
        /* host_messaging typically exposes a single-char or formatted
         * print; adapt to whatever your print_debug / print_hex_byte
         * functions look like in host_messaging.h                     */
        snprintf(buffer + 3*i, 4, "%02x ", buf[i]);
    }
    print_debug(buffer);
    free(buffer);
}

/** Return 0 if buffers are equal, non-zero otherwise (constant-time). */
static int safe_memcmp(const uint8_t *a, const uint8_t *b, uint32_t len)
{
    uint8_t diff = 0;
    for (uint32_t i = 0; i < len; i++) {
        diff |= a[i] ^ b[i];
    }
    return (int)diff;
}

/* ------------------------------------------------------------------ */
/*  Entry point                                                         */
/* ------------------------------------------------------------------ */

/**
 * Encrypt TEST_PLAINTEXT, print the ciphertext, then decrypt it back
 * and verify the result matches the original.
 *
 * Returns 0 on success, a negative wolfcrypt error code on failure.
 */
int test_aes_gcm(void)
{
    Aes     aes;
    int     ret;

    // copy inputs to malloced buffers (4-byte aligned for hardware engine)
    uint8_t *test_plaintext = (uint8_t *)malloc(TEST_PT_SZ);
    uint8_t *test_aad = (uint8_t *)malloc(TEST_AAD_SZ);
    uint8_t *ciphertext = (uint8_t *)malloc(TEST_PT_SZ);
    uint8_t *decrypted = (uint8_t *)malloc(TEST_PT_SZ);
    uint8_t *auth_tag = (uint8_t *)malloc(AUTH_TAG_SZ);
    uint8_t *ciphertext_software = (uint8_t *)malloc(TEST_PT_SZ);
    uint8_t *decrypted_software = (uint8_t *)malloc(TEST_PT_SZ);
    uint8_t *auth_tag_software = (uint8_t *)malloc(AUTH_TAG_SZ);

    if (!ciphertext || !decrypted || !auth_tag || !ciphertext_software || !decrypted_software || !auth_tag_software) {
        print_debug("[test_aes_gcm] failed to allocate memory\n");
        return -1;
    }

    memcpy(test_plaintext, TEST_PLAINTEXT, TEST_PT_SZ);
    memcpy(test_aad, TEST_AAD, TEST_AAD_SZ);
    memcpy(ciphertext, ciphertext, TEST_PT_SZ);
    memcpy(decrypted, decrypted, TEST_PT_SZ);
    memcpy(auth_tag, auth_tag, AUTH_TAG_SZ);
    memcpy(ciphertext_software, ciphertext_software, TEST_PT_SZ);
    memcpy(decrypted_software, decrypted_software, TEST_PT_SZ);
    memcpy(auth_tag_software, auth_tag_software, AUTH_TAG_SZ);

    print_debug("[test_aes_gcm] starting encrypt/decrypt round-trip\n");

    /* ----------------------------------------------------------------
     * Encrypt with hardware crypto callback
     * --------------------------------------------------------------- */
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) {
        print_debug("[test_aes_gcm] wc_AesInit (enc) failed\n");
        return ret;
    }

    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) {
        print_debug("[test_aes_gcm] wc_AesGcmSetKey (enc) failed\n");
        wc_AesFree(&aes);
        return ret;
    }

    ret = wc_AesGcmEncrypt(
        &aes,
        ciphertext,                     /* out          */
        test_plaintext, TEST_PT_SZ,     /* in, sz       */
        TEST_IV,        sizeof(TEST_IV),/* iv, ivSz     */
        auth_tag,       AUTH_TAG_SZ,    /* tag, tagSz   */
        test_aad,       TEST_AAD_SZ     /* aad, aadSz   */
    );

    wc_AesFree(&aes);

    if (ret != 0) {
        print_debug("[test_aes_gcm] wc_AesGcmEncrypt failed\n");
        return ret;
    }

    /*
    * Encrypt with software implementation (for comparison)
    */
    ret = wc_AesInit(&aes, NULL, INVALID_DEVID);
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    ret = wc_AesGcmEncrypt(
        &aes,
        ciphertext_software,
        test_plaintext, TEST_PT_SZ,
        TEST_IV,        sizeof(TEST_IV),
        auth_tag_software, AUTH_TAG_SZ,
        test_aad,       TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    print_debug("[test_aes_gcm] plaintext  : ");
    print_hex("", test_plaintext, TEST_PT_SZ);

    print_debug("[test_aes_gcm] hw ciphertext : ");
    print_hex("", ciphertext, TEST_PT_SZ);
    print_debug("[test_aes_gcm] sw ciphertext : ");
    print_hex("", ciphertext_software, TEST_PT_SZ);

    print_debug("[test_aes_gcm] hw auth tag   : ");
    print_hex("", auth_tag, AUTH_TAG_SZ);
    print_debug("[test_aes_gcm] sw auth tag   : ");
    print_hex("", auth_tag_software, AUTH_TAG_SZ);

    /*
    Check that hardware and software ciphertexts and tags match (they should, since the same key, IV, AAD, and plaintext are used).
    */
    if (safe_memcmp(ciphertext, ciphertext_software, TEST_PT_SZ) != 0) {
        print_debug("[test_aes_gcm] FAIL: hardware and software ciphertexts do not match\n");
        return -1;
    }
    if (safe_memcmp(auth_tag, auth_tag_software, AUTH_TAG_SZ) != 0) {
        print_debug("[test_aes_gcm] FAIL: hardware and software auth tags do not match\n");
        return -1;
    }
    print_debug("[test_aes_gcm] PASS: hardware and software ciphertexts and tags match\n");

    /* ----------------------------------------------------------------
     * Decrypt with hardware crypto callback, verify auth tag
     * --------------------------------------------------------------- */
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) {
        print_debug("[test_aes_gcm] wc_AesInit (dec) failed\n");
        return ret;
    }

    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) {
        print_debug("[test_aes_gcm] wc_AesGcmSetKey (dec) failed\n");
        wc_AesFree(&aes);
        return ret;
    }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,                      /* out          */
        ciphertext, TEST_PT_SZ,         /* in, sz       */
        TEST_IV,    sizeof(TEST_IV),    /* iv, ivSz     */
        auth_tag,   AUTH_TAG_SZ,        /* tag, tagSz   */
        TEST_AAD,   TEST_AAD_SZ         /* aad, aadSz   */
    );

    wc_AesFree(&aes);

    if (ret != 0) {
        /* AES_GCM_AUTH_E (-180) means tag mismatch — data was tampered
         * or the callback produced a wrong tag during encryption.      */
        print_debug("[test_aes_gcm] wc_AesGcmDecrypt failed (tag mismatch?)\n");
        return ret;
    }

    /*
    * Also decrypt with software implementation (for comparison)
    */
    ret = wc_AesInit(&aes, NULL, INVALID_DEVID);
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted_software,
        ciphertext_software, TEST_PT_SZ,
        TEST_IV,            sizeof(TEST_IV),
        auth_tag_software,  AUTH_TAG_SZ,
        test_aad,           TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    print_debug("[test_aes_gcm] hw decrypted  : ");
    print_hex("", decrypted, TEST_PT_SZ);
    print_debug("[test_aes_gcm] sw decrypted  : ");
    print_hex("", decrypted_software, TEST_PT_SZ);

    /* ----------------------------------------------------------------
     * Verify round-trip
     * --------------------------------------------------------------- */
    if (safe_memcmp(decrypted, test_plaintext, TEST_PT_SZ) != 0) {
        print_debug("[test_aes_gcm] FAIL: decrypted output does not match plaintext\n");
        return -1;
    }

    /*
    Compare hardware and software decrypted outputs as well (they should match).
    */
    if (safe_memcmp(decrypted, decrypted_software, TEST_PT_SZ) != 0) {
        print_debug("[test_aes_gcm] FAIL: hardware and software decrypted outputs do not match\n");
        return -1;
    }

    print_debug("[test_aes_gcm] PASS: decrypted output matches plaintext\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Error handling tests                                                */
/*                                                                      */
/*  Verifies that the hardware AES-GCM callback correctly rejects       */
/*  tampered ciphertext, corrupted auth tags, and wrong AAD.            */
/*  Each sub-test expects wc_AesGcmDecrypt to return AES_GCM_AUTH_E.   */
/*                                                                      */
/*  Returns 0 if all error cases are correctly detected,                */
/*  or -1 if any case incorrectly succeeded or failed for the           */
/*  wrong reason.                                                        */
/* ------------------------------------------------------------------ */
int test_aes_gcm_errors(void)
{
    Aes     aes;
    int     ret;
    int     pass = 1;

    /* ----------------------------------------------------------------
     * First, produce a valid ciphertext + tag to tamper with
     * --------------------------------------------------------------- */
    uint8_t ciphertext[TEST_PT_SZ];
    uint8_t auth_tag[AUTH_TAG_SZ];
    uint8_t test_plaintext[TEST_PT_SZ];
    uint8_t test_aad[TEST_AAD_SZ];

    memset(ciphertext, 0, sizeof(ciphertext));
    memset(auth_tag,   0, sizeof(auth_tag));
    memset(test_plaintext, 0, sizeof(test_plaintext));
    memset(test_aad, 0, sizeof(test_aad));

    print_debug("[test_aes_gcm_errors] generating valid ciphertext...\n");

    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("[test_aes_gcm_errors] wc_AesInit failed\n"); return -1; }

    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("[test_aes_gcm_errors] wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmEncrypt(
        &aes,
        ciphertext,
        test_plaintext, TEST_PT_SZ,
        TEST_IV,        sizeof(TEST_IV),
        auth_tag,       AUTH_TAG_SZ,
        test_aad,       TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    if (ret != 0) {
        print_debug("[test_aes_gcm_errors] encrypt failed, cannot run error tests\n");
        return -1;
    }

    uint8_t decrypted[TEST_PT_SZ];

    /*
    * Test 0: Test that an input that is not 4-byte aligned is rejected
    */
    print_debug("[test_aes_gcm_errors] test 0: unaligned input... ");
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }
    ret = wc_AesGcmEncrypt(
        &aes,
        test_plaintext + 1,                  /* out (deliberately unaligned) */
         ciphertext, TEST_PT_SZ,        /* in, sz       */
         TEST_IV,    sizeof(TEST_IV),   /* iv, ivSz     */
         auth_tag,   AUTH_TAG_SZ,       /* tag, tagSz   */
         test_aad,   TEST_AAD_SZ        /* aad, aadSz   */
    );
    if (ret != BAD_FUNC_ARG) {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected BAD_FUNC_ARG, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    } else {
        print_debug("PASS (correctly rejected)\n");
    }
    wc_AesFree(&aes);

    /* ----------------------------------------------------------------
     * Test 1: Tampered ciphertext (flip one bit in the middle)
     * Expected: AES_GCM_AUTH_E
     * --------------------------------------------------------------- */
    print_debug("[test_aes_gcm_errors] test 1: tampered ciphertext... ");

    uint8_t bad_ciphertext[TEST_PT_SZ];
    memcpy(bad_ciphertext, ciphertext, TEST_PT_SZ);
    bad_ciphertext[TEST_PT_SZ / 2] ^= 0x01;   /* flip one bit */

    memset(decrypted, 0, sizeof(decrypted));
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,
        bad_ciphertext, TEST_PT_SZ,
        TEST_IV,        sizeof(TEST_IV),
        auth_tag,       AUTH_TAG_SZ,
        test_aad,       TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    if (ret == AES_GCM_AUTH_E) {
        print_debug("PASS (correctly rejected)\n");
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected AES_GCM_AUTH_E, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    }

    /* ----------------------------------------------------------------
     * Test 2: Tampered auth tag (flip one bit)
     * Expected: AES_GCM_AUTH_E
     * --------------------------------------------------------------- */
    print_debug("[test_aes_gcm_errors] test 2: tampered auth tag... ");

    uint8_t bad_tag[AUTH_TAG_SZ];
    memcpy(bad_tag, auth_tag, AUTH_TAG_SZ);
    bad_tag[0] ^= 0xFF;   /* corrupt first byte entirely */

    memset(decrypted, 0, sizeof(decrypted));
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,
        ciphertext,  TEST_PT_SZ,
        TEST_IV,     sizeof(TEST_IV),
        bad_tag,     AUTH_TAG_SZ,
        test_aad,    TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    if (ret == AES_GCM_AUTH_E) {
        print_debug("PASS (correctly rejected)\n");
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected AES_GCM_AUTH_E, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    }

    /* ----------------------------------------------------------------
     * Test 3: Wrong AAD (different content, same length)
     * Expected: AES_GCM_AUTH_E
     * --------------------------------------------------------------- */
    print_debug("[test_aes_gcm_errors] test 3: wrong AAD content... ");

    static const uint8_t WRONG_AAD[] = "wrong-aad-value";  /* same length as TEST_AAD */

    memset(decrypted, 0, sizeof(decrypted));
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,
        ciphertext,  TEST_PT_SZ,
        TEST_IV,     sizeof(TEST_IV),
        auth_tag,    AUTH_TAG_SZ,
        WRONG_AAD,   TEST_AAD_SZ        /* correct length, wrong bytes */
    );
    wc_AesFree(&aes);

    if (ret == AES_GCM_AUTH_E) {
        print_debug("PASS (correctly rejected)\n");
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected AES_GCM_AUTH_E, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    }

    /* ----------------------------------------------------------------
     * Test 4: Wrong AAD length (truncated by one byte)
     * Expected: AES_GCM_AUTH_E
     * --------------------------------------------------------------- */
    print_debug("[test_aes_gcm_errors] test 4: wrong AAD length... ");

    memset(decrypted, 0, sizeof(decrypted));
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,
        ciphertext,  TEST_PT_SZ,
        TEST_IV,     sizeof(TEST_IV),
        auth_tag,    AUTH_TAG_SZ,
        test_aad,    TEST_AAD_SZ - 1    /* one byte shorter */
    );
    wc_AesFree(&aes);

    if (ret == AES_GCM_AUTH_E) {
        print_debug("PASS (correctly rejected)\n");
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected AES_GCM_AUTH_E, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    }

    /* ----------------------------------------------------------------
     * Test 5: Wrong IV
     * Expected: AES_GCM_AUTH_E
     * --------------------------------------------------------------- */
    print_debug("[test_aes_gcm_errors] test 5: wrong IV... ");

    static const uint8_t WRONG_IV[12] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    };

    memset(decrypted, 0, sizeof(decrypted));
    ret = wc_AesInit(&aes, NULL, HARDWARE_CRYPTO_DEVICE_ID);
    if (ret != 0) { print_debug("wc_AesInit failed\n"); return -1; }
    ret = wc_AesGcmSetKey(&aes, TEST_KEY, sizeof(TEST_KEY));
    if (ret != 0) { wc_AesFree(&aes); print_debug("wc_AesGcmSetKey failed\n"); return -1; }

    ret = wc_AesGcmDecrypt(
        &aes,
        decrypted,
        ciphertext,  TEST_PT_SZ,
        WRONG_IV,    sizeof(WRONG_IV),  /* wrong IV */
        auth_tag,    AUTH_TAG_SZ,
        test_aad,    TEST_AAD_SZ
    );
    wc_AesFree(&aes);

    if (ret == AES_GCM_AUTH_E) {
        print_debug("PASS (correctly rejected)\n");
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "FAIL (expected AES_GCM_AUTH_E, got %d)\n", ret);
        print_debug(buf);
        pass = 0;
    }

    /* ----------------------------------------------------------------
     * Summary
     * --------------------------------------------------------------- */
    if (pass) {
        print_debug("[test_aes_gcm_errors] PASS: all error cases correctly detected\n");
        return 0;
    } else {
        print_debug("[test_aes_gcm_errors] FAIL: one or more error cases not detected\n");
        return -1;
    }
}
